            lookup(side, spinN, sd) {
            const d = this.tbl[side][spinN];
            if (!d) return null;
            const s = d.sd, a = d.ang, p = d.pow, l = s.length;
            // 二分查找最近的两个网格点，然后线性插值
            if (sd <= s[0]) {
                const sa = (a[1]-a[0])/(s[1]-s[0]), sp = (p[1]-p[0])/(s[1]-s[0]);
                return {angle: a[0]+sa*(sd-s[0]), power: p[0]+sp*(sd-s[0])};
            }
            if (sd >= s[l-1]) {
            const sa = (a[l-1]-a[l-2])/(s[l-1]-s[l-2]), sp = (p[l-1]-p[l-2])/(s[l-1]-s[l-2]);
            return {angle: a[l-1]+sa*(sd-s[l-1]), power: p[l-1]+sp*(sd-s[l-1])};
            }
            let lo=0, hi=l-1;
            while (hi-lo > 1) { const m = (lo+hi)>>1; if (s[m]<=sd) lo=m; else hi=m; }
            const t = (sd-s[lo])/(s[hi]-s[lo]);
            return {angle: a[lo]+t*(a[hi]-a[lo]), power: p[lo]+t*(p[hi]-p[lo])};
            },

            getFlightTime(angle, power, gravity) {
            // 经典物理: t = 2 * v0y / g = 2 * V * sinθ / G
            const sinA = Math.sin(angle * Math.PI / 180);
            const velocity = power / 0.004332712;
            return 2 * velocity * sinA / gravity;
            },

            getSDRange(side, spinN) {
            const d = this.tbl[side][spinN];
            if (!d) return null;
            return {min: d.sd[0], max: d.sd[d.sd.length-1]};
            },

            // 判断 SD 是否在实测范围内
            isMeasuredSD(side, spinN, sd) {
            const maxSD = this.measuredMaxSD[side]?.[spinN];
            return maxSD !== undefined && sd <= maxSD + 0.01;
            },

            // 从角度/力度计算像素距离
            // xDist = V² * 2 * cosθ * sinθ / G, V = power / 0.004332712
            computePixelDistance(angleDeg, power) {
                const V = power / 0.004332712;
                return this.getRange(angleDeg, V);
            },

            // 从查找表的角度/力度计算正确的物理像素距离
            // 经典公式: xDist = V² * 2 * cosθ * sinθ / G
            getRange(angleDeg, V) {
            const rad = angleDeg * Math.PI / 180;
            return V * V * 2 * Math.cos(rad) * Math.sin(rad) / this.gravity;
            },
