        // ============ Beta EXE 物理引擎 (V2.1.6 / V2.2.3) ============
        // 从 beta EXE 逆向提取的物理模型
        // V2.1.6: 纯 Forward Euler, 无空气阻力 → 右打差 N=3/4
        // V2.2.3: Forward Euler + 空气阻力 → 所有其他模式
        const BETA_PHYSICS = {
            gravity: 221,
            baseVelocity: 0,
            _scaleComputed: false,
            // === 核心物理常量 ===
            powerMultiplier: 768.245,
            velocityCoeff: 1.295,
            windCoeff: 1.72,
            deg2radDivisor: 57.29,

            // === 时间步长 ===
            // 修正: 0.0055 (来自逆向报告，使旋转计数匹配校准数据)

            // === 距离校准 SCALE (sim units / pixel) ===
            // 通过校准点动态计算
            //   V2.1.6: 61°/2.76 → 800px → SCALE_V216 ≈ 2017.05
            //   V2.2.3: 71°/3.25 → 800px → SCALE_V223 ≈ 1878.00
            SCALE_V216: 0,
            SCALE_V223: 0,

            // === Trico 三球参数 ===
            omega: Math.PI,
            offsetRampRate: 2,
            explosionRadius: 35,
            hitboxWidth: 40,
            hitboxHeight: 33,

            // === 计算初始速度 (beta公式) ===
            calcVelocity(power) {
                return (this.powerMultiplier * power + this.baseVelocity) * this.velocityCoeff;
            },

            // === 计算 power 反解 ===
            calcPower(velocity) {
                return (velocity / this.velocityCoeff - this.baseVelocity) / this.powerMultiplier;
            },

            // === 精确落点计算 (无轨迹存储，用于校准和二分搜索) ===
            // targetElevation: 目标高度(模拟单位, 默认0=平地), 正值=目标更高(上方)
            _simLanding(angleDeg, power, windHorizontal, targetElevation, windVertical) {
                const rad = angleDeg / this.deg2radDivisor;
                const v = this.calcVelocity(power);
                let vx = v * Math.cos(rad);
                let vy = v * Math.sin(rad);
                const we = windHorizontal * this.windCoeff;
                const wv = (windVertical || 0) * this.windCoeff;
                const g = this.gravity;
                let x = 0, y = 0;
                const targetY = targetElevation || 0;
                for (let i = 0; i < 10000; i++) {
                    x += vx; y += vy; vx += we; vy -= g; vy += wv;
                    if (i > 5 && vy < 0 && y <= targetY) {
                        const py = y - vy - g + wv;
                        const f = (py - targetY) / (py - y);
                        return { landX: (x - vx) + f * vx, steps: i + f };
                    }
                }
                return { landX: x, steps: 10000 };
            },

            // === 获取距离校准 SCALE ===
            _ensureScale() {
                if (this._scaleComputed) return;
                const cal216 = this._simLanding(61, 2.76, 0);
                const cal223 = this._simLanding(71, 3.25, 0);
                this.SCALE_V216 = cal216.landX / 800;
                this.SCALE_V223 = cal223.landX / 800;
                this._scaleComputed = true;
            },

            getScale(direction) {
                this._ensureScale();
                return direction === 'right' ? this.SCALE_V216 : this.SCALE_V223;
            },

            // === V2.1.6 纯 Forward Euler 模拟 ===
            // 返回轨迹点数组和最终位置
            // targetElevation: 目标高度(模拟单位, 默认0), 正值=目标更低
            simulateV216(angleDeg, power, windHorizontal, targetElevation) {
                const rad = angleDeg / this.deg2radDivisor;
                const v = this.calcVelocity(power);
                let vx = v * Math.cos(rad);
                let vy = v * Math.sin(rad);
                const windEffect = windHorizontal * this.windCoeff;
                const g = this.gravity;
                const targetY = targetElevation || 0;

                const trajectory = [];
                let x = 0, y = 0;
                const maxSteps = 10000;
                let t = 0;

                for (let i = 0; i < maxSteps; i++) {
                    trajectory.push({ x, y, t: i });
                    x += vx;
                    y += vy;
                    vx += windEffect;
                    vy -= g;
                    t++;
                    // 落地检测（精确插值）
                    if (i > 5 && vy < 0 && y <= targetY) {
                        const py = y - vy - g;
                        const f = (py - targetY) / (py - y);
                        const landX = (x - vx) + f * vx;
                        trajectory.push({ x: landX, y: targetY, t: i + f });
                        return { trajectory, finalX: landX, finalY: targetY, totalTime: i + f, totalSteps: i + f, vx, vy };
                    }
                }

                return { trajectory, finalX: x, finalY: y, totalTime: t, totalSteps: t, vx, vy };
            },

            // === V2.2.3 模拟 (当前: 与V2.1.6相同物理，通过不同SCALE区分) ===
            simulateV223(angleDeg, power, windHorizontal) {
                return this.simulateV216(angleDeg, power, windHorizontal);
            },

            // === 二分搜索: 找到使水平距离=目标距离的 power ===
            binarySearchPower(angleDeg, windHorizontal, targetDistance, useV223) {
                let lo = 0.1, hi = 7.0;
                const maxIter = 60;

                for (let iter = 0; iter < maxIter; iter++) {
                    const mid = (lo + hi) / 2;
                    const land = this._simLanding(angleDeg, mid, windHorizontal);

                    if (Math.abs(land.landX - targetDistance) < 0.1) {
                        // 获取完整轨迹用于碰撞检测
                    }

                    if (land.landX < targetDistance) {
                        lo = mid;
                    } else {
                        hi = mid;
                    }
                }

                const mid = (lo + hi) / 2;
                const land = this._simLanding(angleDeg, mid, windHorizontal);
                const sim = this.simulateV216(angleDeg, mid, windHorizontal);
                return { power: mid, sim, landX: land.landX, steps: land.steps };
            },

            // === 计算水平风力 (从 HTML 2D 风模型转换) ===
            // HTML: windAngleDeg=风向角度, windStrength=风力大小
            // Beta: 水平风= wind * 1.72
            // 左射时翻转vx分量
            getHorizontalWind(windAngleDeg, windStrength, facingLeft) {
                const windRad = windAngleDeg * Math.PI / 180;
                let windX = Math.cos(windRad) * windStrength;
                // 左射时翻转（与getEffectiveWindAngle逻辑一致）
                if (facingLeft) {
                    windX = -windX;
                }
                return windX;
            },

            // === 像素 → 模拟单位 (基于校准SCALE) ===
            pixelToSim(px, direction) {
                return px * this.getScale(direction);
            },

            simToPixel(simUnits, direction) {
                return simUnits / this.getScale(direction);
            },

            // === BETA物理模拟: 从角度/力度计算像素距离 ===
            // 用于Trico查找表的xDist计算 (查找表基于BETA物理校准)
            getBetaPixelDistance(angleDeg, power, direction) {
                const result = this._simLanding(angleDeg, power, 0);
                const scale = this.getScale(direction);
                return result.landX / scale;
            },
        };

        
        // ============ Trico 3-in-1 新物理模型 (g=221, K=994.88, 固定ω) ============
        // 基于 OpenBound 源码参数: 连续弹道模型, 固定角速度旋转
        // N=1-3: 查表角度/力度 + 物理公式推导
        // N=4: R_smooth边界角推导
        // 风力/落差: 时间算法 (timeSolve)

        const TRICO_NEW = {
            g: 221,
            K: 768.245 * 1.295,  // = 994.877...
            OMEGA_L: 0.6544,
            OMEGA_R: 0.5571,
            POWER_LIMIT: 6.0,
            SPIN_RADIUS: 35,
            OFFSET_RAMP_RATE: 2,
            WIND_COEFF: 1.72,
            N4_WIND_COEFF: 1.143,
            N4_RECOGNITION_WIND_SCALE: 0.01025,

            // 连续弹道: R = (p*K)^2 * sin(2θ) / g
            R_cont(angleDeg, power) {
                return Math.pow(power * this.K, 2) * Math.sin(2 * angleDeg * Math.PI / 180) / this.g;
            },
            // 平滑距离公式 (N=4用)
            R_smooth(sd) {
                return 1425.12 * sd + 0.5914 * sd * sd;
            },
            // 飞行时间: T = 2*p*K*sin(θ) / g
            flightTime(angleDeg, power) {
                return 2 * power * this.K * Math.sin(angleDeg * Math.PI / 180) / this.g;
            },
            // 从R和角度反推力度
            powerFromRange(R, angleDeg) {
                const s = Math.sin(2 * angleDeg * Math.PI / 180);
                return s <= 0.0001 ? null : Math.sqrt(R * this.g / (this.K * this.K * s));
            },
            // N=4 边界角
            boundaryAngle(R, omega, N) {
                const i = N * 2 * Math.PI / (omega * Math.sqrt(2 * R / this.g));
                return Math.min(Math.atan(i * i) * 180 / Math.PI, 89.5);
            },
            // 时间算法: 给定飞行时间T, 射程R, 风力we, 落差elev -> 求(vx,vy,angle,power)
            timeSolve(T, R, we, elev) {
                const g = this.g;
                const vy = (elev + 0.5 * g * T * T) / T;
                const vx = (R - 0.5 * we * T * T) / T;
                if (vx <= 0) return null;
                const v0 = Math.sqrt(vx * vx + vy * vy);
                if (vy < 0) return null;
                const a = Math.atan2(vy, vx) * 180 / Math.PI;
                if (a < 0.5 || a > 89.5) return null;
                return { angle: a, power: v0 / this.K, vx, vy, v0, T };
            },
        };

