                const windX = Math.cos(windRad) * windForce;
                const windY = Math.sin(windRad) * windForce;
                const elevationUi = elevationInternal / ELEVATION_PIXELS_PER_UNIT;
                const strongUpGate = this.smoothStep01((Math.max(0, windStrength || 0) - 23) / 2)
