                    const downHeadGate = this.smoothStep01((Math.abs(windX) - 12) / 3)
                        * this.smoothStep01((-windY - 2) / 3)
                        * this.smoothStep01((Math.max(0, windStrength || 0) - 12) / 4)
                        * this.smoothStep01((20 - Math.max(0, windStrength || 0)) / 6)
