                if (!wp || wp.effGrav <= 0) return null;
                const features = this.getRederivedFeatureVector(
                    this.rederivedPhasePhysicsN123.features, side, distance, elevationInternal, windAngle, windStrength
                );
                const factor = this.getRederivedOriginFactor(elevationInternal, windStrength);
                const timeBias = this.dotCoefficients(group.time, features) * factor;
                const xABias = this.dotCoefficients(group.xA, features) * factor;
