                const T2 = this.getSpinTime(sdParts, side, 2, distance, elevationInternal, windAngle, windStrength, n2Table);
                const T3 = this.getSpinTime(sdParts, side, 3, distance, elevationInternal, windAngle, windStrength, n3Table);
                if (!Number.isFinite(T2) || !Number.isFinite(T3) || T2 <= 0 || T3 <= 0 || T3 <= T2) return null;
                const T4 = T3 + (T3 - T2);
