                const visualTime = 2 * power * TRICO_NEW.K * Math.sin(angleRad) / TRICO_NEW.g;
                const targetX = TRICO_NEW.R_smooth(sdDistance);
                const pixelDistance = sdDistance * DISTANCE_PIXELS_PER_20SD;
                const xScale = pixelDistance / targetX;
                const yScale = pixelDistance / q;
                const visualXA = (xA * q) / (Tq * Tq);
                const effVisualGrav = (effGrav * q) / (Tq * Tq);
